import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        List<Integer> ones = new ArrayList<>();

        for (int i = 1; i <= n; i++) {
            int a = sc.nextInt();
            if (a == 1) {
                ones.add(i);
            }
        }

        long answer = 0;
        int m = ones.size();

        for (int i = 0; i < m; i++) {
            int pos = ones.get(i);
            int prev = (i == 0 ? 0 : ones.get(i - 1));
            int next = (i == m - 1 ? n + 1 : ones.get(i + 1));

            answer += (long) (pos - prev) * (next - pos);
        }

        System.out.println(answer);
    }
}
